SELECT a.APPLICATION_ID, a.APPLICATION_NO, p.FULL_NAME_AR APPLICANT_NAME_AR, p.NATIONAL_ID, a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, a.STATUS_CODE, q.INQUIRY_ID, q.REQUEST_DATE, q.RESPONSE_DATE, q.CREDIT_SCORE, q.RESULT_CODE, q.REFERENCE_NO FROM MFF_APPLICATIONS a JOIN MFF_PERSONS p ON p.PERSON_ID = a.PRIMARY_PERSON_ID JOIN MFF_ORGANIZATIONS o ON o.ORG_ID = a.FINANCIER_ID LEFT JOIN MFF_CREDIT_INQUIRIES q ON q.APPLICATION_ID = a.APPLICATION_ID WHERE a.STATUS_CODE IN ('CREDIT_INQUIRY','CREDIT_ACCEPTED');
